package bowling

import "errors"

var (
	errNegativeRoll   = errors.New("Negative roll is invalid")
	errPinCount       = errors.New("Pin count exceeds pins on the lane")
	errGameOver       = errors.New("Cannot roll after game is over")
	errIncompleteGame = errors.New("Score cannot be taken until the end of the game")
)

// Game tracks the rolls of a bowling game and can compute its score.
type Game struct {
	rolls       []int
	frame       int // current frame, 0-9
	rollInFrame int // number of rolls recorded in the current frame (0-2)
	bonusLimit  int // max pins allowed on the next roll in the tenth frame; 0 = no limit
	gameOver    bool
}

// NewGame returns a new, empty bowling game.
func NewGame() *Game {
	return &Game{}
}

// Roll records a roll of pins, validating it against the rules of bowling.
func (g *Game) Roll(pins int) error {
	if g.gameOver {
		return errGameOver
	}
	if pins < 0 {
		return errNegativeRoll
	}
	if pins > 10 {
		return errPinCount
	}

	if g.frame < 9 {
		if g.rollInFrame == 0 {
			g.rolls = append(g.rolls, pins)
			if pins == 10 {
				g.advanceFrame()
			} else {
				g.rollInFrame = 1
			}
			return nil
		}
		if pins > 10-g.rolls[len(g.rolls)-1] {
			return errPinCount
		}
		g.rolls = append(g.rolls, pins)
		g.advanceFrame()
		return nil
	}

	// Tenth frame: strikes and spares earn one or two bonus rolls.
	switch g.rollInFrame {
	case 0:
		g.rolls = append(g.rolls, pins)
		g.rollInFrame = 1
		if pins != 10 {
			g.bonusLimit = 10 - pins
		}
	case 1:
		last := g.rolls[len(g.rolls)-1]
		if last == 10 {
			// First bonus roll after a strike is unconstrained.
			g.rolls = append(g.rolls, pins)
			g.rollInFrame = 2
			if pins != 10 {
				g.bonusLimit = 10 - pins
			}
		} else {
			if pins > g.bonusLimit {
				return errPinCount
			}
			g.rolls = append(g.rolls, pins)
			if last+pins == 10 {
				// Spare: one unconstrained bonus roll.
				g.rollInFrame = 2
				g.bonusLimit = 0
			} else {
				g.gameOver = true
			}
		}
	default:
		if g.bonusLimit != 0 && pins > g.bonusLimit {
			return errPinCount
		}
		g.rolls = append(g.rolls, pins)
		g.gameOver = true
	}
	return nil
}

// Score returns the total score of a completed game.
func (g *Game) Score() (int, error) {
	if !g.gameOver {
		return 0, errIncompleteGame
	}
	total := 0
	i := 0
	for frame := 0; frame < 10; frame++ {
		switch {
		case g.rolls[i] == 10:
			total += 10 + g.rolls[i+1] + g.rolls[i+2]
			i++
		case g.rolls[i]+g.rolls[i+1] == 10:
			total += 10 + g.rolls[i+2]
			i += 2
		default:
			total += g.rolls[i] + g.rolls[i+1]
			i += 2
		}
	}
	return total, nil
}

// advanceFrame moves to the next frame, resetting per-frame state.
func (g *Game) advanceFrame() {
	g.frame++
	g.rollInFrame = 0
	g.bonusLimit = 0
}
